<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref} from 'vue';
import {LayoutDashboard,X} from 'lucide-vue-next';
import BiAppCreationForm from './BiAppCreationForm.vue';
const props=defineProps<{tenant:string;tenantName:string;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{close:[];updated:[];project:[id:string];notice:[message:string];created:[resource:string]}>();
const dialog=ref<HTMLElement|null>(null);let previous:HTMLElement|null=null;
function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('close');return;}if(event.key!=='Tab')return;const items=[...dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,a[href],[tabindex="0"]')??[]].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(!first){event.preventDefault();return;}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
onMounted(async()=>{previous=document.activeElement as HTMLElement|null;await nextTick();dialog.value?.querySelector<HTMLElement>('.app-creation-close')?.focus();});
onUnmounted(()=>previous?.isConnected&&previous.focus({preventScroll:true}));
</script>
<template><Teleport to="body"><div class="modal-backdrop app-creation-backdrop" @click.self="emit('close')"><section ref="dialog" class="app-creation-dialog" role="dialog" aria-modal="true" aria-label="Nova aplicação" @keydown="keydown"><header><span><LayoutDashboard :size="24"/></span><div><small>UM NOVO PONTO DE PARTIDA</small><h2>Nova aplicação</h2><p>{{tenantName}} · Minha Mesa</p></div><button class="icon-button app-creation-close" aria-label="Fechar criação de aplicação" @click="emit('close')"><X :size="20"/></button></header><div class="app-creation-content"><BiAppCreationForm :tenant="tenant" :tenant-name="tenantName" :request="request" @created="emit('created',$event)" @updated="emit('updated')" @project="emit('project',$event)" @notice="emit('notice',$event)"/></div></section></div></Teleport></template>
<style scoped>.app-creation-backdrop{z-index:125}.app-creation-dialog{width:min(780px,calc(100vw - 40px));max-height:calc(100dvh - 40px);display:flex;flex-direction:column;background:#fff;border:1px solid #e0e8f5;border-radius:18px;box-shadow:0 24px 100px #14263d26;overflow:hidden}.app-creation-dialog>header{display:flex;gap:14px;align-items:flex-start;padding:25px 28px;border-bottom:1px solid #e6edf7;flex-shrink:0}.app-creation-dialog>header>span{display:grid;place-items:center;width:44px;height:44px;background:#edf4ff;color:#1163e9;border-radius:11px;flex-shrink:0}.app-creation-dialog>header>div{min-width:0}.app-creation-dialog small{font-size:9px;letter-spacing:2px;color:#8295af}.app-creation-dialog h2{font-size:22px;margin:7px 0;color:#233f65}.app-creation-dialog header p{font-size:12px;color:#8092aa;margin:0}.app-creation-close{margin-left:auto;flex-shrink:0}.app-creation-content{padding:8px 28px 26px;overflow:auto;overscroll-behavior:contain;min-height:0}.app-creation-dialog button:focus-visible{outline:2px solid #1163e9;outline-offset:3px}@media(max-width:600px){.app-creation-dialog{width:calc(100vw - 22px);max-height:calc(100dvh - 24px);border-radius:13px}.app-creation-dialog>header{padding:18px;gap:10px}.app-creation-dialog h2{font-size:18px}.app-creation-dialog small{font-size:8px;letter-spacing:1.3px}.app-creation-content{padding:2px 18px 20px}}</style>
